using ModConfigEnhance.Overview;
using ModConfigEnhance.Updating;
using Newtonsoft.Json;
int n=0;void Check(bool ok,string why){if(!ok)throw new Exception(why);n++;}
string home=Path.Combine(AppContext.BaseDirectory,"s-"+Guid.NewGuid().ToString("N"));BepInEx.Paths.ConfigPath=home;OverviewUpdateQueue.Root=Path.Combine(home,"worker");Directory.CreateDirectory(OverviewUpdateQueue.Root);
ResourceOperationDraft.Stage(new(){Action="shop",Shop=new(){Namespace="Team",Package="Mod",Version="1"}});ResourceOperationDraft.Stage(new(){Action="shop",Shop=new(){Namespace="Team",Package="Mod",Version="2"}});Check(ResourceOperationDraft.Count==1&&ResourceOperationDraft.Snapshot().Single().Shop!.Version=="2","same package retains final target");
string id=Guid.NewGuid().ToString("N");ResourceOperationDraft.BeginSubmission(id);bool locked=false;try{ResourceOperationDraft.Remove(ResourceOperationDraft.Snapshot().Single().Id);}catch(InvalidOperationException){locked=true;}Check(locked&&ResourceOperationDraft.Count==1,"waiting acknowledgement locks edits and retains draft");
string rejected=Path.Combine(OverviewUpdateQueue.Root,"command-rejections",id+".json");Directory.CreateDirectory(Path.GetDirectoryName(rejected)!);File.WriteAllText(rejected,"{}");Check(ResourceOperationDraft.SubmissionId==""&&ResourceOperationDraft.Count==1,"durable rejection unlocks without discarding goals");
ResourceOperationDraft.Stage(new(){Action="shop",Shop=new(){Namespace="Team",Package="Other"}});Check(ResourceOperationDraft.Count==2,"user can correct rejected batch");
string next=Guid.NewGuid().ToString("N");ResourceOperationDraft.BeginSubmission(next);
void Receipt(string commandId){string path=Path.Combine(OverviewUpdateQueue.Root,"command-receipts",commandId+".json");Directory.CreateDirectory(Path.GetDirectoryName(path)!);File.WriteAllText(path,JsonConvert.SerializeObject(new{Status="accepted"}));}
Receipt(id);Check(!ResourceOperationDraft.SubmissionAccepted()&&ResourceOperationDraft.Count==2,"unrelated accepted batch cannot consume draft");
Receipt(next);Check(ResourceOperationDraft.Count==0&&ResourceOperationDraft.SubmissionId=="","exact durable acceptance clears recovery and unlocks");ResourceOperationDraft.Stage(new(){Action="shop",Shop=new(){Namespace="Team",Package="Update",Operation="preview-install"}});ResourceOperationDraft.Stage(new(){Action="shop",Shop=new(){Namespace="Team",Package="Remove",Operation="preview-uninstall"}});
var subset=ResourceOperationDraft.Snapshot().Where(c=>!ResourceOperationDraft.IsUpdate(c)).ToArray();string subsetId=Guid.NewGuid().ToString("N");ResourceOperationDraft.BeginSubmission(subsetId,subset);Receipt(subsetId);Check(ResourceOperationDraft.PendingUpdates().Count==1&&ResourceOperationDraft.Count==1,"config resource acknowledgement never clears unrelated pending updates");
ResourceOperationDraft.RemoveSubmittedUpdates(ResourceOperationDraft.PendingUpdates().Select(c=>c.Id));Check(ResourceOperationDraft.Count==0,"independent update removes only transferred pending operations");Console.WriteLine($"PASS {n} production resource-draft checks");
